mapper.select:
SELECT A.ev_cd, COUNT(*) AS event_count FROM tbl_event_data A LEFT JOIN tbl_device B ON A.ev_dv_id = B.dv_id WHERE 1=1 AND
AND ( A.ev_car_num LIKE CONCAT('%', #{searchKeyword}, '%') OR B.dv_addr LIKE CONCAT('%', #{searchKeyword}, '%') OR B.dv_name LIKE CONCAT('%', #{searchKeyword}, '%') )
AND LEFT(A.ev_date, 8) BETWEEN #{startDate} AND #{endDate}
AND A.ev_action = #{evAction}
GROUP BY A.ev_cd ORDER BY A.ev_cd

WITH filtered AS ( SELECT A.ev_id, ROW_NUMBER() OVER ( ORDER BY
ev_date ev_cd dv_name dv_addr ev_car_num ev_date
ASC DESC
, ev_id DESC ) AS rn FROM tbl_event_data A LEFT JOIN tbl_device B ON A.ev_dv_id = B.dv_id WHERE 1=1 AND
AND ( A.ev_car_num like CONCAT('%',#{searchKeyword},'%') OR B.dv_addr like CONCAT('%',#{searchKeyword},'%') OR B.dv_name like CONCAT('%',#{searchKeyword},'%'))
AND LEFT(A.ev_date, 8) BETWEEN #{startDate} AND #{endDate}
AND A.ev_cd = #{evCd}
AND A.ev_action = #{evAction}
) SELECT ev_id FROM filtered WHERE rn = (SELECT rn FROM filtered WHERE ev_id = #{currentEvId}) + #{step}

